package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevDept string // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var ErRec EmpRec

var empFile *os.File
var scanner *bufio.Scanner

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func storeDecimal(val decimal.Decimal, intDigits, decDigits int, rounded bool) decimal.Decimal {
	var scaled decimal.Decimal
	if rounded {
		scaled = val.Round(int32(decDigits))
	} else {
		scaled = val.Truncate(int32(decDigits))
	}
	total := intDigits + decDigits
	if total == 0 {
		return decimal.NewFromInt(0)
	}
	mod := decimal.New(1, int32(total))
	scaledInt := scaled.Shift(int32(decDigits)).Truncate(0)
	abs := scaledInt.Abs()
	q := abs.Div(mod).Truncate(0)
	rem := abs.Sub(q.Mul(mod))
	if scaledInt.Sign() < 0 {
		rem = rem.Neg()
	}
	result := rem.Shift(int32(-decDigits))
	return result
}

func storeInt(v int64, n int) int64 {
	mod := int64(1)
	for i := 0; i < n; i++ {
		mod *= 10
	}
	if v < 0 {
		abs := -v
		rem := abs % mod
		return -rem
	}
	return v % mod
}

func countPlaceholders(s string) int {
	c := 0
	for _, ch := range s {
		if ch == 'Z' || ch == '9' {
			c++
		}
	}
	return c
}

func formatEdited(val decimal.Decimal, pic string) string {
	isNeg := val.Sign() < 0
	// work with absolute value
	absVal := val.Abs()

	dotPos := strings.Index(pic, ".")
	var intPic, decPic string
	if dotPos == -1 {
		intPic = pic
		decPic = ""
	} else {
		intPic = pic[:dotPos]
		decPic = pic[dotPos+1:]
	}
	intPlaces := countPlaceholders(intPic)
	decPlaces := countPlaceholders(decPic)
	totalPlaces := intPlaces + decPlaces

	var scaledInt decimal.Decimal
	if decPlaces > 0 {
		scaledInt = absVal.Shift(int32(decPlaces)).Truncate(0)
	} else {
		scaledInt = absVal.Truncate(0)
	}

	mod := decimal.New(1, int32(totalPlaces))
	q := scaledInt.Div(mod).Truncate(0)
	rem := scaledInt.Sub(q.Mul(mod))
	if rem.Sign() < 0 {
		rem = rem.Neg()
	}
	remStr := rem.Truncate(0).StringFixed(0)
	// StringFixed may return like "0" for zero
	if remStr == "" {
		remStr = "0"
	}
	// Handle possible negative sign in remStr (should not happen)
	if strings.HasPrefix(remStr, "-") {
		remStr = remStr[1:]
	}
	// Remove any decimal point that StringFixed might produce (should not for 0 scale)
	if idx := strings.Index(remStr, "."); idx != -1 {
		remStr = remStr[:idx]
	}
	if len(remStr) < totalPlaces {
		remStr = strings.Repeat("0", totalPlaces-len(remStr)) + remStr
	} else if len(remStr) > totalPlaces {
		remStr = remStr[len(remStr)-totalPlaces:]
	}

	picRunes := []rune(pic)
	result := make([]rune, len(picRunes))
	digitsIdx := 0
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			result[i] = rune(remStr[digitsIdx])
			digitsIdx++
		} else {
			result[i] = ch
		}
	}

	intEnd := len(picRunes)
	if dotPos != -1 {
		intEnd = dotPos
	}
	// Z suppression
	suppress := true
	for i := 0; i < intEnd; i++ {
		ch := picRunes[i]
		if ch == 'Z' || ch == '9' {
			cur := result[i]
			if ch == 'Z' && suppress && cur == '0' {
				result[i] = ' '
			} else {
				suppress = false
			}
		}
	}
	// commas
	significant := false
	for i := 0; i < intEnd; i++ {
		ch := picRunes[i]
		if ch == 'Z' || ch == '9' {
			if result[i] != ' ' {
				significant = true
			}
		} else if ch == ',' {
			if !significant {
				result[i] = ' '
			}
		}
	}

	s := string(result)
	if isNeg {
		// place minus in first space before first significant digit
		// find first significant position
		firstSig := -1
		for i := 0; i < intEnd; i++ {
			if picRunes[i] == 'Z' || picRunes[i] == '9' {
				if result[i] != ' ' {
					firstSig = i
					break
				}
			}
		}
		if firstSig != -1 {
			placed := false
			for j := firstSig - 1; j >= 0; j-- {
				if result[j] == ' ' {
					result[j] = '-'
					placed = true
					s = string(result)
					break
				}
			}
			if !placed && firstSig == 0 {
				// overwrite first char
				result[0] = '-'
				s = string(result)
			}
		}
	}
	return s
}

func parseNumeric(s string, scale int) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	digitsStr := b.String()
	if digitsStr == "" {
		return decimal.NewFromInt(0)
	}
	// digitsStr length small, parse via decimal
	d, err := decimal.NewFromString(digitsStr)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return d.Shift(int32(-scale))
}

func parseEmpRec(line string) EmpRec {
	id := line[0:5]
	dept := line[5:8]
	hoursStr := line[8:12]
	rateStr := line[12:17]
	hours := parseNumeric(hoursStr, 1)
	rate := parseNumeric(rateStr, 2)
	return EmpRec{
		ErId:    id,
		ErDept:  dept,
		ErHours: hours,
		ErRate:  rate,
	}
}

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 17 {
			line += strings.Repeat(" ", 17-len(line))
		} else if len(line) > 17 {
			line = line[:17]
		}
		ErRec = parseEmpRec(line)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = ErRec.ErDept
		WsFirstFlag = "N"
	} else {
		if ErRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = ErRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if ErRec.ErHours.GreaterThan(forty) {
		WsRegHours = storeDecimal(forty, 3, 1, false)
		diff := ErRec.ErHours.Sub(forty)
		WsOtHours = storeDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = storeDecimal(ErRec.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.NewFromInt(0), 3, 1, false)
	}
	rate := ErRec.ErRate
	onePointFive := decimal.New(15, -1)
	part1 := WsRegHours.Mul(rate)
	part2 := WsOtHours.Mul(rate).Mul(onePointFive)
	grossRaw := part1.Add(part2)
	WsGross = storeDecimal(grossRaw, 7, 2, true)

	newDept := WsDeptTotal.Add(WsGross)
	WsDeptTotal = storeDecimal(newDept, 9, 2, false)
	WsDeptCount = storeInt(WsDeptCount+1, 3)

	newGrand := WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(newGrand, 11, 2, false)
	WsGrandCount = storeInt(WsGrandCount+1, 5)

	WsHoursEd = formatEdited(ErRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(ErRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", ErRec.ErId, ErRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func MainPara() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer empFile.Close()
	scanner = bufio.NewScanner(empFile)
	// increase buffer if needed
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	// CLOSE already deferred
	GrandPara()
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0

	MainPara()
}
